// Recupera a ocorrencia completa que foi guardada na fila de falhas
return $input.all().map((item) => ({
  json: {
    ...item.json.payload,
    falha_id: item.json.falha_id,
    tentativas_anteriores: item.json.tentativas,
  },
}));

// Junta a resposta da IA (real ou mock) com os dados da ocorrencia
const bases = $('Restaurar ocorrência').all();
const entradas = $input.all();

return entradas.map((item, i) => {
  const r = item.json;
  let base = bases.find(b => b.json.id === r.id)?.json;
  if (!base) base = $('Restaurar ocorrência').itemMatching(i).json;

  const categoriaSugerida = r.categoria_sugerida ?? base.categoria;
  const confianca = Number(r.confianca ?? 0);

  const motivosRevisao = [];
  if (confianca < 0.7) motivosRevisao.push('confianca baixa da IA');
  if (categoriaSugerida !== base.categoria) motivosRevisao.push('IA sugeriu outra categoria');
  if (base.duplicata) motivosRevisao.push('possivel duplicata da ocorrencia ' + base.dup_id);

  return {
    json: {
      ...base,
      categoria_sugerida: categoriaSugerida,
      confianca,
      modelo_ia: r.modelo ?? 'desconhecido',
      justificativa_ia: r.justificativa ?? '',
      precisa_revisao: motivosRevisao.length > 0,
      motivos_revisao: motivosRevisao,
    },
  };
});

